import { createRoute, z } from '@hono/zod-openapi'

const MessageContextSchema = z
  .object({
    message_id: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The ID of the message to which this message is a reply.',
        example: 'wamid.gBGGSFcCNEOPAgkO_KJ55r4w_ww',
      }),
  })
  .openapi({ description: 'Context information for replying to a message', required: [] })
  .openapi('MessageContext')

const BaseMessagePropertiesSchema = z
  .object({
    messaging_product: z.string().openapi({ example: 'whatsapp' }),
    recipient_type: z
      .enum(['individual', 'group'])
      .openapi({ description: 'The type of recipient.', example: 'individual' }),
    to: z
      .string()
      .openapi({
        description:
          "The recipient's phone number for individual messages, and group-id for group message.",
        example: '19505550005',
      }),
    type: z.string().openapi({ description: 'The type of message' }),
    context: MessageContextSchema.exactOptional(),
  })
  .openapi({
    description: 'Common properties shared by all message types',
    required: ['messaging_product', 'recipient_type', 'to', 'type'],
  })
  .openapi('BaseMessageProperties')

const TextMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({
      type: z.literal('text').exactOptional(),
      text: z
        .strictObject({
          body: z
            .string()
            .exactOptional()
            .openapi({ description: 'The text of the message.', example: 'Hello World!' }),
          preview_url: z.boolean().exactOptional(),
        })
        .openapi({ required: [] }),
    })
    .openapi({ required: ['text'] }),
).openapi('TextMessage')

const MediaObjectSchema = z
  .xor([
    z
      .object({
        id: z
          .string()
          .openapi({
            description: 'The media object ID. **Required when `link` is not used.**',
            example: 'MEDIA_OBJECT_ID',
          }),
      })
      .openapi({ required: ['id'] }),
    z
      .object({
        link: z
          .url()
          .openapi({
            description: 'The protocol and URL of the media to be sent (HTTP/HTTPS only).',
            example: 'http(s)://example.com/media.mp4',
          }),
      })
      .openapi({ required: ['link'] }),
  ])
  .openapi({ description: 'A media object. Either `id` or `link` is required.' })
  .openapi('MediaObject')

const AudioMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({ type: z.literal('audio').exactOptional(), audio: MediaObjectSchema })
    .openapi({ required: ['audio'] }),
).openapi('AudioMessage')

const DocumentMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({ type: z.literal('document').exactOptional(), document: MediaObjectSchema })
    .openapi({ required: ['document'] }),
).openapi('DocumentMessage')

const ImageMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({ type: z.literal('image').exactOptional(), image: MediaObjectSchema })
    .openapi({ required: ['image'] }),
).openapi('ImageMessage')

const LocationMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({
      type: z.literal('location').exactOptional(),
      location: z
        .strictObject({
          address: z
            .string()
            .exactOptional()
            .openapi({
              description: 'The address of the location.',
              example: '1 Hacker Way, Menlo Park, CA 94025',
            }),
          latitude: z
            .string()
            .exactOptional()
            .openapi({ description: 'The latitude of the location.', example: 37.4847 }),
          longitude: z
            .string()
            .exactOptional()
            .openapi({ description: 'The longitude of the location.', example: -122.1486 }),
          name: z
            .string()
            .exactOptional()
            .openapi({ description: 'The name of the location.', example: 'Meta HQ' }),
        })
        .openapi({ required: [] }),
    })
    .openapi({ required: ['location'] }),
).openapi('LocationMessage')

const VideoMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({ type: z.literal('video').exactOptional(), video: MediaObjectSchema })
    .openapi({ required: ['video'] }),
).openapi('VideoMessage')

const StickerMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({
      type: z.literal('sticker').exactOptional(),
      sticker: z.xor([
        z
          .strictObject({ id: z.string().openapi({ description: 'The ID of the sticker.' }) })
          .openapi({ required: ['id'] }),
        z
          .strictObject({ link: z.string().openapi({ description: 'The URL of the sticker.' }) })
          .openapi({ required: ['link'] }),
      ]),
    })
    .openapi({ required: ['sticker'] }),
).openapi('StickerMessage')

const ReactionMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({
      type: z.literal('reaction').exactOptional(),
      reaction: z
        .strictObject({
          emoji: z.string().exactOptional().openapi({ description: 'emoji' }),
          message_id: z.string().exactOptional().openapi({ description: 'reacted message-id' }),
        })
        .openapi({ required: [] }),
    })
    .openapi({ required: ['reaction'] }),
).openapi('ReactionMessage')

const HeaderObjectSchema = z
  .object({
    type: z
      .enum(['text', 'video', 'image', 'document'])
      .openapi({ description: 'The header type.' }),
    text: z
      .string()
      .max(60)
      .exactOptional()
      .openapi({
        description:
          "Text for the header. Required if 'type' is 'text'. Emojis supported, no markdown.",
      }),
    sub_text: z
      .string()
      .max(60)
      .exactOptional()
      .openapi({ description: 'Optional sub-text for the header. Emojis supported, no markdown.' }),
    document: MediaObjectSchema.exactOptional().openapi({
      description: "Contains the media object for this document. Required if 'type' is 'document'.",
    }),
    image: MediaObjectSchema.exactOptional().openapi({
      description: "Contains the media object for this image. Required if 'type' is 'image'.",
    }),
    video: MediaObjectSchema.exactOptional().openapi({
      description: "Contains the media object for this video. Required if 'type' is 'video'.",
    }),
  })
  .openapi({
    description:
      "Header content displayed on top of a message. Required for 'product_list' type. Cannot be set for 'product' type.",
    required: ['type'],
  })
  .openapi('HeaderObject')

const BodyObjectSchema = z
  .object({
    text: z
      .string()
      .max(1024)
      .openapi({
        description: 'The content of the message body. Emojis and markdown are supported.',
      }),
  })
  .openapi({
    description:
      "An object with the body of the message. Optional for 'product' type, required for other interactive message types.",
    required: ['text'],
  })
  .openapi('BodyObject')

const FooterObjectSchema = z
  .object({
    text: z
      .string()
      .max(60)
      .openapi({ description: 'The footer content. Emojis, markdown, and links are supported.' }),
  })
  .openapi({
    description: 'An object with the footer of the message. Optional.',
    required: ['text'],
  })
  .openapi('FooterObject')

const SectionObjectSchema = z
  .object({
    title: z
      .string()
      .max(24)
      .exactOptional()
      .openapi({
        description:
          'Title of the section. Required if the message has more than one section. Max 24 characters.',
      }),
    product_items: z
      .array(
        z
          .object({
            product_retailer_id: z
              .string()
              .openapi({ description: 'Unique identifier of the product in a catalog.' }),
          })
          .openapi({ required: ['product_retailer_id'] }),
      )
      .min(1)
      .max(30)
      .exactOptional()
      .openapi({ description: 'Array of product objects.' }),
    rows: z
      .array(
        z
          .object({
            id: z.string().max(200).openapi({ description: 'Unique row identifier.' }),
            title: z.string().max(24).openapi({ description: 'Row title.' }),
            description: z
              .string()
              .max(72)
              .exactOptional()
              .openapi({ description: 'Optional row description.' }),
          })
          .openapi({ required: ['id', 'title'] }),
      )
      .max(10)
      .exactOptional()
      .openapi({ description: 'Contains a list of rows.' }),
  })
  .openapi({
    description: 'A section object, used in List Messages and Multi-Product Messages.',
    required: [],
  })
  .openapi('SectionObject')

const ActionObjectSchema = z
  .xor([
    z
      .object({
        button: z
          .string()
          .max(20)
          .openapi({
            description:
              'Button content for List Messages. Cannot be empty, must be unique. Emojis supported, no markdown.',
          }),
        sections: z
          .array(SectionObjectSchema)
          .min(1)
          .max(10)
          .openapi({ description: 'Array of section objects.' }),
      })
      .openapi({ required: ['button', 'sections'] }),
    z
      .object({
        buttons: z
          .array(
            z
              .object({
                type: z
                  .literal('reply')
                  .openapi({ description: 'Only supported type is "reply" for Reply Button.' }),
                reply: z
                  .object({
                    id: z
                      .string()
                      .max(256)
                      .openapi({
                        description:
                          'Unique identifier for your button. No leading/trailing spaces.',
                      }),
                    title: z
                      .string()
                      .max(20)
                      .openapi({
                        description:
                          'Button title. Cannot be empty, must be unique. Emojis supported, no markdown.',
                      }),
                  })
                  .openapi({ required: ['id', 'title'] }),
              })
              .openapi({ required: ['type', 'reply'] }),
          )
          .min(1)
          .max(3)
          .openapi({ description: 'Array of button objects.' }),
      })
      .openapi({ required: ['buttons'] }),
    z
      .object({
        catalog_id: z
          .string()
          .openapi({
            description:
              'Unique identifier of the Facebook catalog linked to your WhatsApp Business Account.',
          }),
        product_retailer_id: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Unique identifier of the product in a catalog. Required for Single Product Messages.',
          }),
        sections: z
          .array(SectionObjectSchema)
          .min(1)
          .max(10)
          .exactOptional()
          .openapi({ description: 'Array of section objects.' }),
      })
      .openapi({ required: ['catalog_id'] }),
    z
      .object({
        name: z.literal('catalog_message'),
        parameters: z
          .object({
            thumbnail_product_retailer_id: z
              .string()
              .openapi({ description: 'Product retailer ID for the thumbnail.' }),
          })
          .openapi({ required: ['thumbnail_product_retailer_id'] }),
      })
      .openapi({ required: ['name', 'parameters'] }),
    z
      .object({
        name: z.literal('flow'),
        parameters: z
          .xor([
            z
              .unknown()
              .superRefine((val, ctx) => {
                if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                  if (!Object.hasOwn(val, 'flow_id')) {
                    ctx.addIssue({ code: 'custom' })
                  }
                }
              })
              .openapi({ required: ['flow_id'] }),
            z
              .unknown()
              .superRefine((val, ctx) => {
                if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                  if (!Object.hasOwn(val, 'flow_name')) {
                    ctx.addIssue({ code: 'custom' })
                  }
                }
              })
              .openapi({ required: ['flow_name'] }),
          ])
          .openapi({ required: ['flow_message_version', 'flow_cta'] }),
      })
      .openapi({ required: ['name', 'parameters'] }),
    z.object({ name: z.literal('call_permission_request') }).openapi({ required: ['name'] }),
  ])
  .openapi({
    description:
      'Action you want the user to perform after reading the message. Its structure varies by interactive message type.',
  })
  .openapi('ActionObject')

const InteractiveObjectSchema = z
  .object({
    type: z
      .enum([
        'button',
        'call_permission_request',
        'catalog_message',
        'list',
        'product',
        'product_list',
        'flow',
      ])
      .openapi({ description: 'The type of interactive message to send.' }),
    header: HeaderObjectSchema.exactOptional(),
    body: BodyObjectSchema.exactOptional(),
    footer: FooterObjectSchema.exactOptional(),
    action: ActionObjectSchema,
  })
  .openapi({
    description: 'An object containing the content for an interactive message.',
    required: ['type', 'action'],
  })
  .openapi('InteractiveObject')

const InteractiveMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({
      type: z.literal('interactive').exactOptional(),
      interactive: InteractiveObjectSchema,
    })
    .openapi({ required: ['interactive'] }),
).openapi('InteractiveMessage')

const LanguageObjectSchema = z
  .object({
    policy: z
      .literal('deterministic')
      .openapi({
        description: 'The language policy the message should follow.',
        example: 'deterministic',
      }),
    code: z
      .string()
      .openapi({
        description: 'The code of the language or locale to use (e.g., `"en"`, `"en_US"`).',
        example: 'en_US',
      }),
  })
  .openapi({ required: ['policy', 'code'] })
  .openapi('LanguageObject')

const TemplateComponentSchema = z
  .object({
    type: z
      .enum(['header', 'body', 'button'])
      .openapi({ description: 'Describes the component type.' }),
    sub_type: z
      .enum(['quick_reply', 'url', 'catalog'])
      .exactOptional()
      .openapi({
        description:
          'Required when `type=button`. Not used for other types. Type of button to create.',
      }),
    parameters: z
      .array(z.any())
      .exactOptional()
      .openapi({ description: 'Array of parameter objects with the content of the message.' }),
    index: z
      .string()
      .regex(/^[2-6, 11-14]$/)
      .exactOptional()
      .openapi({
        description:
          'Required when `type=button`. Not used for other types. Position index of the button (0-9).',
        example: '0',
      }),
  })
  .openapi({
    required: ['type'],
    discriminator: {
      propertyName: 'type',
      mapping: {
        header: '#/components/schemas/HeaderComponent',
        body: '#/components/schemas/BodyComponent',
        button: '#/components/schemas/ButtonComponent',
      },
    },
  })
  .openapi('TemplateComponent')

const TemplateObjectSchema = z
  .object({
    name: z.string().openapi({ description: 'Name of the template.', example: 'TEMPLATE_NAME' }),
    language: LanguageObjectSchema.openapi({
      description:
        'Contains a `language` object. Specifies the language the template may be rendered in',
    }),
    components: z
      .array(TemplateComponentSchema)
      .exactOptional()
      .openapi({
        description: 'Array of `components` objects containing the parameters of the message.',
        example: [
          {
            type: 'header',
            parameters: [{ type: 'image', image: { link: 'http(s)://example.com/image.jpg' } }],
          },
          {
            type: 'body',
            parameters: [
              { type: 'text', text: 'Hello {{1}}! Your order of {{2}} is confirmed for {{3}}.' },
            ],
          },
          {
            type: 'button',
            sub_type: 'quick_reply',
            index: '0',
            parameters: [{ type: 'payload', payload: 'ORDER_DETAILS_CLICKED' }],
          },
        ],
      }),
  })
  .openapi({ required: ['name', 'language'] })
  .openapi('TemplateObject')

const TemplateMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .object({ type: z.literal('template').exactOptional(), template: TemplateObjectSchema })
    .openapi({ required: ['template'] }),
).openapi('TemplateMessage')

const AddressObjectSchema = z
  .strictObject({
    city: z.string().exactOptional().openapi({ description: 'City name', example: 'Menlo Park' }),
    country: z
      .string()
      .exactOptional()
      .openapi({ description: 'Full country name', example: 'United States' }),
    country_code: z
      .string()
      .exactOptional()
      .openapi({ description: 'Two-letter ISO country code', example: 'us' }),
    state: z.string().exactOptional().openapi({ description: 'State abbreviation', example: 'CA' }),
    street: z
      .string()
      .exactOptional()
      .openapi({ description: 'Street address', example: '1 Hacker Way' }),
    type: z.enum(['HOME', 'WORK']).exactOptional().openapi({ description: 'Address type' }),
    zip: z.string().exactOptional().openapi({ description: 'ZIP code', example: '94025' }),
  })
  .openapi({ required: [] })
  .openapi('AddressObject')

const EmailObjectSchema = z
  .strictObject({
    email: z.email().openapi({ description: 'Email address', example: 'test@fb.com' }),
    type: z.enum(['HOME', 'WORK']).exactOptional().openapi({ description: 'Email type' }),
  })
  .openapi({ required: ['email'] })
  .openapi('EmailObject')

const NameObjectSchema = z
  .strictObject({
    first_name: z.string().exactOptional().openapi({ description: 'First name', example: 'John' }),
    formatted_name: z
      .string()
      .exactOptional()
      .openapi({ description: 'Formatted full name', example: 'John Smith' }),
    last_name: z.string().exactOptional().openapi({ description: 'Last name', example: 'Smith' }),
    middle_name: z.string().exactOptional().openapi({ description: 'Middle name', example: 'D.' }),
    prefix: z.string().exactOptional().openapi({ description: 'Name prefix', example: 'Dr' }),
    suffix: z.string().exactOptional().openapi({ description: 'Name suffix', example: 'Jr' }),
  })
  .openapi({ required: [] })
  .openapi('NameObject')

const OrganizationObjectSchema = z
  .strictObject({
    company: z
      .string()
      .exactOptional()
      .openapi({ description: 'Company name', example: 'WhatsApp' }),
    department: z
      .string()
      .exactOptional()
      .openapi({ description: 'Department name', example: 'Design' }),
    title: z.string().exactOptional().openapi({ description: 'Job title', example: 'Manager' }),
  })
  .openapi({ required: [] })
  .openapi('OrganizationObject')

const PhoneObjectSchema = z
  .strictObject({
    phone: z.string().openapi({ description: 'Phone number', example: '+1 (650) 555-1234' }),
    type: z.enum(['HOME', 'WORK']).exactOptional().openapi({ description: 'Phone type' }),
    wa_id: z
      .string()
      .exactOptional()
      .openapi({ description: 'WhatsApp ID', example: '16505551234' }),
  })
  .openapi({ required: ['phone'] })
  .openapi('PhoneObject')

const UrlObjectSchema = z
  .strictObject({
    type: z.enum(['HOME', 'WORK']).exactOptional().openapi({ description: 'URL type' }),
    url: z.url().openapi({ description: 'URL', example: 'https://www.facebook.com' }),
  })
  .openapi({ required: ['url'] })
  .openapi('UrlObject')

const ContactObjectSchema = z
  .strictObject({
    addresses: z
      .array(AddressObjectSchema)
      .exactOptional()
      .openapi({ description: 'Full contact address(es)' }),
    birthday: z.iso
      .date()
      .exactOptional()
      .openapi({ description: 'Date of birth (YYYY-MM-DD format)', example: '2012-08-18' }),
    emails: z
      .array(EmailObjectSchema)
      .exactOptional()
      .openapi({ description: 'Contact email address(es)' }),
    name: NameObjectSchema.exactOptional().openapi({ description: 'Contact name object' }),
    org: OrganizationObjectSchema.exactOptional().openapi({
      description: 'Contact organization information',
    }),
    phones: z
      .array(PhoneObjectSchema)
      .exactOptional()
      .openapi({ description: 'Contact phone number(s)' }),
    urls: z.array(UrlObjectSchema).exactOptional().openapi({ description: 'Contact URL(s)' }),
  })
  .openapi({ required: [] })
  .openapi('ContactObject')

const ContactsMessageSchema = BaseMessagePropertiesSchema.and(
  z
    .strictObject({
      type: z.literal('contacts').exactOptional(),
      contacts: z.array(ContactObjectSchema).min(1).max(5),
    })
    .openapi({ required: ['contacts'] }),
).openapi('ContactsMessage')

type MessageType =
  | z.infer<typeof TextMessageSchema>
  | z.infer<typeof AudioMessageSchema>
  | z.infer<typeof DocumentMessageSchema>
  | z.infer<typeof ImageMessageSchema>
  | z.infer<typeof LocationMessageSchema>
  | z.infer<typeof VideoMessageSchema>
  | z.infer<typeof StickerMessageSchema>
  | z.infer<typeof ReactionMessageSchema>
  | z.infer<typeof InteractiveMessageSchema>
  | z.infer<typeof TemplateMessageSchema>
  | z.infer<typeof ContactsMessageSchema>

const BusinessVerificationStatusSchema = z
  .enum(['VERIFIED', 'UNVERIFIED', 'PENDING', 'REJECTED'])
  .openapi({
    description: 'Verification status of the connected client business',
    example: 'VERIFIED',
  })
  .openapi('BusinessVerificationStatus')

const BusinessStatusSchema = z
  .enum(['ACTIVE', 'INACTIVE', 'SUSPENDED', 'PENDING_APPROVAL'])
  .openapi({ description: 'Current status of the connected client business', example: 'ACTIVE' })
  .openapi('BusinessStatus')

const ConnectedClientBusinessSchema = z
  .object({
    id: z
      .string()
      .openapi({
        description: 'Unique identifier for the connected client business',
        example: '1234567890123456',
      }),
    name: z
      .string()
      .min(1)
      .max(255)
      .openapi({
        description: 'Name of the connected client business',
        example: 'Example Client Business',
      }),
    verification_status: BusinessVerificationStatusSchema.exactOptional(),
    business_status: BusinessStatusSchema.exactOptional(),
    created_time: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'Timestamp when the business connection was created',
        example: '2023-01-15T10:30:00Z',
      }),
    updated_time: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'Timestamp when the business connection was last updated',
        example: '2023-06-20T14:45:00Z',
      }),
  })
  .openapi({
    description: 'Connected client business information and configuration',
    required: ['id', 'name'],
  })
  .openapi('ConnectedClientBusiness')

const CursorPagingSchema = z
  .object({
    cursors: z
      .object({
        before: z
          .string()
          .exactOptional()
          .openapi({
            description: 'Cursor pointing to the start of the page of data',
            example: 'QVFIUjNpUWpVWmRBd0dn',
          }),
        after: z
          .string()
          .exactOptional()
          .openapi({
            description: 'Cursor pointing to the end of the page of data',
            example: 'QVFIUjNpUWpVWmRBd0Rn',
          }),
      })
      .exactOptional()
      .openapi({ required: [] }),
    previous: z
      .string()
      .exactOptional()
      .openapi({
        description: 'URL for the previous page of results',
        example:
          'https://graph.facebook.com/v23.0/1234567890/connected_client_businesses?before=QVFIUjNpUWpVWmRBd0Dn',
      }),
    next: z
      .string()
      .exactOptional()
      .openapi({
        description: 'URL for the next page of results',
        example:
          'https://graph.facebook.com/v23.0/1234567890/connected_client_businesses?after=QVFIUjNpUWpVWmRBd0Rn',
      }),
  })
  .openapi({ description: 'Cursor-based pagination information', required: [] })
  .openapi('CursorPaging')

const ConnectedClientBusinessesResponseSchema = z
  .object({
    data: z
      .array(ConnectedClientBusinessSchema)
      .exactOptional()
      .openapi({ description: 'Array of connected client businesses' }),
    paging: CursorPagingSchema.exactOptional(),
  })
  .openapi({ description: 'Response containing list of connected client businesses', required: [] })
  .openapi('ConnectedClientBusinessesResponse')

const GraphAPIErrorSchema = z
  .object({
    error: z
      .object({
        message: z
          .string()
          .openapi({ description: 'Human-readable error message', example: 'Invalid parameter' }),
        type: z.string().openapi({ description: 'Error category type', example: 'OAuthException' }),
        code: z.int().openapi({ description: 'Numeric error code', example: 100 }),
        error_subcode: z
          .int()
          .exactOptional()
          .openapi({ description: 'More specific error subcode when available', example: 33 }),
        fbtrace_id: z
          .string()
          .exactOptional()
          .openapi({
            description: 'Unique identifier for debugging and support requests with Meta',
            example: 'AXsgnV2Cm3ZMGF3dF_cfYIn',
          }),
        is_transient: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Indicates whether this error is temporary and the request should be retried',
            example: false,
          }),
        error_user_title: z
          .string()
          .exactOptional()
          .openapi({
            description: 'User-friendly error title for display purposes',
            example: 'Permission Denied',
          }),
        error_user_msg: z
          .string()
          .exactOptional()
          .openapi({
            description: 'User-friendly error message for display purposes',
            example: "Your app doesn't have permission to access this resource",
          }),
      })
      .openapi({ required: ['message', 'type', 'code'] }),
  })
  .openapi({ description: 'Standard Graph API error response', required: ['error'] })
  .openapi('GraphAPIError')

