const CallPermissionCheckResponsePayloadSchema = z
  .object({
    messaging_product: z
      .string()
      .openapi({ example: 'whatsapp', description: 'Messaging product' }),
    permission: z
      .object({
        status: z
          .enum(['granted', 'pending', 'denied', 'expired'])
          .openapi({
            example: 'granted',
            description: 'Current permission status for calling this user',
          }),
        expiration_time: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .exactOptional()
          .openapi({
            type: 'integer',
            format: 'int64',
            example: 1735689600,
            description: 'Unix timestamp when the permission expires (if applicable)',
          }),
      })
      .openapi({ required: ['status'], description: 'Call permission details' }),
    actions: z
      .array(
        z
          .object({
            action_name: z
              .enum(['start_call', 'send_call_permission_request'])
              .openapi({ example: 'start_call', description: 'Name of the action' }),
            can_perform_action: z
              .boolean()
              .openapi({
                example: true,
                description: 'Whether the business can perform this action',
              }),
            limits: z
              .array(
                z
                  .object({
                    time_period: z
                      .string()
                      .openapi({ example: '24h', description: 'Time period for the limit' }),
                    current_usage: z
                      .int()
                      .openapi({ example: 5, description: 'Current usage count' }),
                    max_allowed: z
                      .int()
                      .openapi({ example: 100, description: 'Maximum allowed usage' }),
                    limit_expiration_time: z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64(),
                      )
                      .exactOptional()
                      .openapi({
                        type: 'integer',
                        format: 'int64',
                        example: 1735689600,
                        description: 'Unix timestamp when the limit resets',
                      }),
                  })
                  .openapi({ required: ['time_period', 'current_usage', 'max_allowed'] }),
              )
              .exactOptional()
              .openapi({ description: 'Rate limits for this action' }),
          })
          .openapi({ required: ['action_name', 'can_perform_action'] }),
      )
      .exactOptional()
      .openapi({ description: 'Available actions and their restrictions' }),
  })
  .openapi({ required: ['messaging_product', 'permission'] })
  .openapi('CallPermissionCheckResponsePayload')

