export const getVersionPhoneNumberIDGroupsRoute = createRoute({
  method: 'get',
  path: '/{Version}/{Phone-Number-ID}/groups',
  summary: 'Get Active Groups',
  description: 'Retrieve a list of active groups for a given business phone number',
  operationId: 'getActiveGroups',
  request: {
    headers: z.object({
      'User-Agent': UserAgentParamsSchema,
      Authorization: AuthorizationParamsSchema,
      'Content-Type': ContentTypeParamsSchema,
    }),
    params: z.object({
      Version: z
        .string()
        .openapi({
          param: { name: 'Version', in: 'path', required: true, schema: { type: 'string' } },
        }),
      'Phone-Number-ID': z
        .string()
        .openapi({
          param: {
            name: 'Phone-Number-ID',
            in: 'path',
            required: true,
            description: 'Business phone number ID',
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(1024),
        )
        .default(25)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Number of groups to fetch in the request',
            schema: { type: 'integer', minimum: 1, maximum: 1024, default: 25 },
            required: false,
          },
        }),
      after: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'after',
            in: 'query',
            description: 'Cursor that points to the end of a page of data',
            schema: { type: 'string' },
            required: false,
          },
        }),
      before: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'before',
            in: 'query',
            description: 'Cursor that points to the beginning of a page of data',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List of active groups',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z
                .object({
                  groups: z
                    .array(
                      z
                        .object({
                          id: z.string().exactOptional().openapi({ description: 'Group ID' }),
                          subject: z
                            .string()
                            .exactOptional()
                            .openapi({ description: 'Group subject' }),
                          created_at: z
                            .string()
                            .exactOptional()
                            .openapi({ description: 'Group creation timestamp' }),
                        })
                        .openapi({ required: [] }),
                    )
                    .exactOptional(),
                })
                .exactOptional()
                .openapi({ required: [] }),
              paging: PagingInfoSchema.exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  security: [{ bearerAuth: [] }],
})

export const postVersionPhoneNumberIDGroupsRoute = createRoute({
  method: 'post',
  path: '/{Version}/{Phone-Number-ID}/groups',
  summary: 'Create Group',
  description: 'Create a new group and get an invite link',
  operationId: 'createGroup',
  request: {
    headers: z.object({
      'User-Agent': UserAgentParamsSchema,
      Authorization: AuthorizationParamsSchema,
      'Content-Type': ContentTypeParamsSchema,
    }),
    params: z.object({
      Version: z
        .string()
        .openapi({
          param: { name: 'Version', in: 'path', required: true, schema: { type: 'string' } },
        }),
      'Phone-Number-ID': z
        .string()
        .openapi({
          param: {
            name: 'Phone-Number-ID',
            in: 'path',
            required: true,
            description: 'Business phone number ID',
            schema: { type: 'string' },
            example: '12784358810',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              messaging_product: z
                .literal('whatsapp')
                .openapi({ description: 'Messaging product' }),
              subject: z
                .string()
                .max(128)
                .openapi({
                  description: 'Group subject. Maximum 128 characters. Whitespace is trimmed.',
                  example: 'New Purchase Inquiry',
                }),
              description: z
                .string()
                .max(2048)
                .exactOptional()
                .openapi({
                  description: 'Group description. Maximum 2048 characters.',
                  example:
                    'Jim, an existing client, would like to learn about new car purchase options for current year models.',
                }),
              join_approval_mode: z
                .enum(['approval_required', 'auto_approve'])
                .default('auto_approve')
                .exactOptional()
                .openapi({
                  description:
                    'Indicates if WhatsApp users who click the invitation link can join the group with or without being approved first.\n- approval_required: WhatsApp users must be approved via join request before they can access the group\n- auto_approve: WhatsApp users can join the group without approval\n',
                }),
            })
            .openapi({ required: ['messaging_product', 'subject'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Group creation request submitted successfully',
      content: {
        'application/json': {
          schema: z
            .object({
              messaging_product: z.string().exactOptional().openapi({ example: 'whatsapp' }),
              request_id: z
                .string()
                .exactOptional()
                .openapi({ description: 'Group creation request ID', example: '106540352242922' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    500: InternalServerErrorResponse,
  },
  security: [{ bearerAuth: [] }],
})

