export const getVersionMediaIDRoute = createRoute({
  method: 'get',
  path: '/{Version}/{Media-ID}',
  tags: ['Media'],
  summary: 'Retrieve Media URL',
  description:
    'To retrieve your media’s URL, make a **GET** call to **`/{{Media-ID}}`**. Use the returned URL to download the media file. Note that clicking this URL (i.e. performing a generic GET) will not return the media; you must include an access token. For more information, see [Download Media](https://developers.facebook.com/docs/business-messaging/whatsapp/business-phone-numbers/media#download-media).\n\nYou can also use the optional query **`?phone_number_id`** for **`Retrieve Media URL`** and **`Delete Media`**. This parameter checks to make sure the media belongs to the phone number before retrieval or deletion.\n\n#### Response\n\nA successful response includes an object with a media URL. The URL is only valid for 5 minutes. To use this URL, see [Download Media](https://developers.facebook.com/docs/business-messaging/whatsapp/business-phone-numbers/media#download-media).',
  operationId: 'retrieveMediaUrl',
  request: {
    params: z.object({
      Version: z
        .string()
        .openapi({
          param: { name: 'Version', in: 'path', required: true, schema: { type: 'string' } },
        }),
      'Media-ID': z
        .string()
        .openapi({
          param: { name: 'Media-ID', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    headers: z.object({
      'User-Agent': UserAgentParamsSchema,
      Authorization: AuthorizationParamsSchema,
    }),
    query: z.object({
      phone_number_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'phone_number_id',
            in: 'query',
            schema: { type: 'string', example: '<PHONE_NUMBER_ID>' },
            description:
              'Specifies that this action only be performed if the media belongs to the provided phone number.',
            required: false,
          },
          example: '<PHONE_NUMBER_ID>',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Retrieve Media URL',
      content: {
        'application/json': {
          schema: z
            .object({
              file_size: z.string().exactOptional().openapi({ example: '303833' }),
              id: z.string().exactOptional().openapi({ example: '2621233374848975' }),
              messaging_product: z.string().exactOptional().openapi({ example: 'whatsapp' }),
              mime_type: z.string().exactOptional().openapi({ example: 'image/jpeg' }),
              sha256: z.string().exactOptional().openapi({ example: '<HASH>' }),
              url: z.string().exactOptional().openapi({ example: '<URL>' }),
            })
            .openapi({ required: [] }),
          examples: {
            'Retrieve Media URL': {
              value: {
                file_size: '303833',
                id: '2621233374848975',
                messaging_product: 'whatsapp',
                mime_type: 'image/jpeg',
                sha256: '<HASH>',
                url: '<URL>',
              },
            },
          },
        },
      },
    },
  },
  security: [{ bearerAuth: [] }],
})

